#include <stdio.h>

/* teste do desafio minutos-e-segundos — counter_protocol (03-tdd 3.9.3).
   Fase SAIDA: a captura do stdout acontece DENTRO do teste (freopen manda o
   stdout para um arquivo temporario proprio do cenario, o teste chama a
   funcao do aluno, fflush descarrega e o arquivo e lido de volta). O main e
   o relatorio sao do harness. */

/* prototipo da funcao do aluno (o teste declara o que exercita) */
void minutosESegundos(void);

SM_TEST(as_tres_decomposicoes) {
    freopen("sm_saida_1.tmp", "w", stdout);
    minutosESegundos();
    fflush(stdout);

    FILE *f = fopen("sm_saida_1.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("215 segundos", linha, "215 segundos sao 3 min e 35 s\n",
              "215 / 60 da 3 minutos e 215 % 60 deixa 35 segundos");
    fgets(linha, 80, f);
    checa_str("500 segundos", linha, "500 segundos sao 8 min e 20 s\n",
              "500 / 60 da 8 minutos e 500 % 60 deixa 20 segundos");
    fgets(linha, 80, f);
    checa_str("3725 segundos", linha, "3725 segundos sao 62 min e 5 s\n",
              "3725 / 60 da 62 minutos e 3725 % 60 deixa 5 segundos");
    fclose(f);
}

SM_TEST(a_saida_acaba_na_terceira_linha) {
    freopen("sm_saida_2.tmp", "w", stdout);
    minutosESegundos();
    fflush(stdout);

    FILE *f = fopen("sm_saida_2.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    fgets(linha, 80, f);
    fgets(linha, 80, f);
    char fim[80] = "(nada impresso)";
    fgets(fim, 80, f);
    checa_str("nao ha linha a mais", fim, "(nada impresso)",
              "a saida acaba na terceira linha: nenhuma linha extra e aceita");
    fclose(f);
}

