#include <stdio.h>

void minutosESegundos(void) {
    printf("215 segundos sao %d min e %d s\n", 215 / 60, 215 % 60);
    printf("500 segundos sao %d min e %d s\n", 500 / 60, 500 % 60);
    printf("3725 segundos sao %d min e %d s\n", 3725 / 60, 3725 % 60);
}
